import{_ as a}from"./chunks/ubuntu22-logo.CEahdcMS.js";import{_ as e,o as i,c as o,a5 as d}from"./chunks/framework.DGp912Ge.js";const k=JSON.parse('{"title":"개발자 가이드","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/developers-guide.md","filePath":"ko/software/developers-guide.md","lastUpdated":1785806767000}'),l={name:"ko/software/developers-guide.md"};function s(r,t,n,h,c,u){return i(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="개발자-가이드" tabindex="-1">개발자 가이드 <a class="header-anchor" href="#개발자-가이드" aria-label="Permalink to &quot;개발자 가이드&quot;">​</a></h1><h2 id="소개" tabindex="-1">소개 <a class="header-anchor" href="#소개" aria-label="Permalink to &quot;소개&quot;">​</a></h2><p><strong>RBQ 시뮬레이션, 명령 및 배포/업데이트 매뉴얼에 오신 것을 환영합니다</strong></p><p>이 매뉴얼은 RBQ 로봇을 <strong>시뮬레이션</strong>하고 명령을 보내며, 실제 로봇에 직접 개발한 알고리즘을 <strong>배포</strong>하는 과정을 종합적으로 설명합니다.</p><h2 id="개발자를-위한-시뮬레이터-및-gui" tabindex="-1">개발자를 위한 시뮬레이터 및 GUI <a class="header-anchor" href="#개발자를-위한-시뮬레이터-및-gui" aria-label="Permalink to &quot;개발자를 위한 시뮬레이터 및 GUI&quot;">​</a></h2><ul><li>RBQ 로봇은 <strong>MuJoCo</strong>를 사용해 정밀하게 시뮬레이션할 수 있습니다. 📝 <em>시뮬레이션 환경 &quot;playground&quot;는 다음 파일을 편집하여 수정할 수 있습니다:</em> <code>resources/model/rbq_environment.xml</code></li><li><strong>RBQ GUI</strong>는 로봇에 명령을 보내고 상태를 모니터링하는 직관적인 인터페이스를 제공합니다. <ul><li>로봇 상태와 센서 상태를 시각적으로 확인할 수 있으며, 키보드와 조이스틱 입력을 모두 지원합니다.</li></ul></li></ul><h2 id="gui-개요" tabindex="-1">GUI 개요 <a class="header-anchor" href="#gui-개요" aria-label="Permalink to &quot;GUI 개요&quot;">​</a></h2><ul><li>이 섹션에서는 <strong>RBQ GUI</strong> 사용 방법과 주요 기능, 인터페이스 구성을 설명합니다.</li></ul><p>GUI Connect</p><ul><li>[1] : 상단 패널</li><li>[2] : 중앙 패널</li><li>[3] : 3D 패널</li></ul><h3 id="상단-패널" tabindex="-1">상단 패널 <a class="header-anchor" href="#상단-패널" aria-label="Permalink to &quot;상단 패널&quot;">​</a></h3><p>상단 패널에는 로봇 연결, 초기 자세, 모터 상태 확인 등 핵심 기능이 모여 있습니다. 비상 정지 버튼과 배터리 전압 및 IMU 센서 상태 표시기도 이 패널에 있습니다.</p><ul><li><strong>Connection Status and Buttons:</strong> 로봇의 연결 상태를 표시합니다. 이 버튼으로 로봇에 연결하거나 연결을 끊을 수 있습니다.</li><li><strong>Auto Start</strong> 버튼: [Motor Check → Initialize Pose → Control Start] 순서로 로봇을 자동으로 초기화하고 제어 시스템을 준비합니다.</li><li><strong>Motor Check / Initialize Pose / Control Start</strong> 버튼: 각 시작 동작을 개별적으로 실행할 수 있습니다. 일반적으로는 <strong>Auto Start</strong> 버튼 사용을 권장합니다.<br> 📝 <em>시뮬레이션: Control Start 버튼만 초록색으로 표시됩니다. 실제 로봇: 준비 완료 시 세 버튼의 표시등이 모두 초록색으로 바뀝니다.</em></li><li><strong>EMERGENCY</strong> 버튼: 로봇의 모든 동작을 즉시 중단하고 로봇을 부드럽게 내려앉힙니다. <ul><li>비상 정지 후 동작을 재개하려면 <strong>Gait select</strong> 그룹 박스에서 <strong>Stance</strong> 버튼을 누르세요. 📝 <em>RECOVERY 모드(노란색)를 거친 후 stance motion(초록색)으로 전환됩니다.</em></li></ul></li></ul><h3 id="중앙-패널" tabindex="-1">중앙 패널 <a class="header-anchor" href="#중앙-패널" aria-label="Permalink to &quot;중앙 패널&quot;">​</a></h3><ul><li><p>중앙 패널에는 로봇에 다양한 명령을 보낼 수 있는 탭과 버튼이 있습니다. 📝 <em>실제 로봇에서는 <strong>관절, 펌웨어, 전원</strong> 탭이 추가로 표시되지만, 일반적인 사용 시에는 건드리지 않는 것이 좋습니다.</em></p></li><li><p><strong>[ 보행 탭 ]</strong> 로봇의 걷기 동작과 보행 모드 전환을 명령합니다.</p><table><tr><th style="text-align:center;">✅ 버튼 동작</th><th style="text-align:center;">Sit</th><th style="text-align:center;">Stance</th><th style="text-align:center;">Walk</th><th style="text-align:center;">Stairs</th></tr><tr><th style="text-align:center;">⌨️ 키보드 키</th><th style="text-align:center;">1</th><th style="text-align:center;">2</th><th style="text-align:center;">3</th><th style="text-align:center;">4</th></tr></table></li></ul><h3 id="_3d-패널" tabindex="-1">3D 패널 <a class="header-anchor" href="#_3d-패널" aria-label="Permalink to &quot;3D 패널&quot;">​</a></h3><ul><li>연결된 로봇의 현재 자세를 3D로 렌더링한 디지털 트윈을 표시합니다.</li></ul><h2 id="설치" tabindex="-1">설치 <a class="header-anchor" href="#설치" aria-label="Permalink to &quot;설치&quot;">​</a></h2><ul><li>이 섹션에서는 RBQ 로봇 시뮬레이션 및 개발 환경을 처음부터 설치하고 구성하는 방법을 설명합니다.</li></ul><h3 id="시스템-요구사항" tabindex="-1">시스템 요구사항 <a class="header-anchor" href="#시스템-요구사항" aria-label="Permalink to &quot;시스템 요구사항&quot;">​</a></h3><p>원활한 시뮬레이션 및 개발 환경 구동을 위해 다음 사양을 권장합니다:</p><ul><li>운영 체제: Ubuntu 22.04 (x86) <img src="'+a+`" alt="GUI Connect"></li><li>최소 PC 사양: <ul><li>CPU: Intel Core i7 12세대</li><li>RAM: 16 GB</li><li>저장 공간: 25 GB</li></ul></li><li>제어 장치 <ul><li>키보드: W, A, S, D, Q, E, R, F, [1-5] 키</li><li>조이스틱: Logitech Wireless Gamepad F710 (권장) GUI Connect</li></ul></li></ul><h3 id="_1-rbq-저장소-다운로드" tabindex="-1">1. RBQ 저장소 다운로드 <a class="header-anchor" href="#_1-rbq-저장소-다운로드" aria-label="Permalink to &quot;1. RBQ 저장소 다운로드&quot;">​</a></h3><ul><li>아래 명령어로 저장소를 클론하세요:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span></code></pre></div><blockquote><p>모든 스크립트, 바이너리, SDK 코드는 <code>RBQ/</code> 아래에 있습니다. 모든 명령어는 이 디렉토리에서 실행하세요.</p></blockquote><blockquote><p><strong>참고:</strong> 사전 빌드된 바이너리가 <code>bin/</code>에 포함되어 있으므로 별도 빌드 단계는 필요하지 않습니다.</p></blockquote><h2 id="▶-시뮬레이션" tabindex="-1">▶ 시뮬레이션 <a class="header-anchor" href="#▶-시뮬레이션" aria-label="Permalink to &quot;▶ 시뮬레이션&quot;">​</a></h2><ul><li>아래 스크립트로 <strong>RBQ 제어 모듈, MuJoCo 시뮬레이터, GUI</strong>를 한 번에 실행합니다.</li></ul><p><strong>참고:</strong> <em><code>인자:</code></em></p><ul><li><code>--help</code> : 도움말 메시지를 출력하고 종료합니다.</li><li><code>--vision</code> : 비전 모듈을 함께 실행합니다 (예: 비전 센서, 계단 오르기 활성화).</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span></span></code></pre></div><ul><li>프롬프트가 표시되면 새로 열린 CLI 터미널에 <code>사용자 비밀번호</code>를 입력해 프로세스를 시작합니다.</li></ul><h3 id="초기화-시뮬레이션-로봇-연결-및-시작" tabindex="-1">초기화 - 시뮬레이션 로봇 연결 및 시작 <a class="header-anchor" href="#초기화-시뮬레이션-로봇-연결-및-시작" aria-label="Permalink to &quot;초기화 - 시뮬레이션 로봇 연결 및 시작&quot;">​</a></h3><ul><li><code>RBQ GUI</code>에서 <strong>Connect</strong> 버튼을 클릭해 연결합니다. <ul><li>성공하면 <code>연결 표시등</code>이 <strong>Simulator Connected</strong> 텍스트와 함께 <strong>파란색</strong>으로 바뀝니다.</li></ul></li><li><code>RBQ GUI</code>에서 <strong>Auto Start</strong> 버튼을 클릭해 제어를 시작합니다. <ul><li>성공하면 <code>제어 표시등</code>이 <strong>초록색</strong>으로 변경됩니다.</li></ul></li></ul><h3 id="stance-로봇이-서도록-명령하기" tabindex="-1">Stance - 로봇이 서도록 명령하기 <a class="header-anchor" href="#stance-로봇이-서도록-명령하기" aria-label="Permalink to &quot;Stance - 로봇이 서도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; tab --&gt; &quot;Gait select&quot; group-box --&gt; &quot;Stance&quot; 버튼</code> 또는 키보드 <code>2</code>를 누르세요</li><li>명령을 내리면 로봇이 기립 자세로 이동하기 시작합니다. 완료 후 추가 명령에 응답합니다. <ul><li>📝 <em>현재 자세에 따라 기립 자세로 전환하는 데 몇 초가 걸릴 수 있습니다.</em></li></ul></li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Nose up / down</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Roll Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td>Height up / down</td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full range of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결된 경우 키보드 숫자 키만 유효합니다.</em></li></ul><h3 id="walk-로봇이-걷도록-명령하기" tabindex="-1">Walk - 로봇이 걷도록 명령하기 <a class="header-anchor" href="#walk-로봇이-걷도록-명령하기" aria-label="Permalink to &quot;Walk - 로봇이 걷도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Walk&quot; 버튼</code> 또는 키보드 <code>3</code>을 누르세요</li><li>명령을 내리면 로봇이 걷기 보행으로 전환됩니다. 완료 후 추가 명령에 응답합니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td>Pitch Forward / Backward</td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결된 경우 키보드 숫자 키만 유효합니다.</em></li></ul><h3 id="stair-로봇이-계단을-오르도록-명령하기" tabindex="-1">Stair - 로봇이 계단을 오르도록 명령하기 <a class="header-anchor" href="#stair-로봇이-계단을-오르도록-명령하기" aria-label="Permalink to &quot;Stair - 로봇이 계단을 오르도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Stairs&quot; 버튼</code> 또는 키보드 <code>4</code>를 누르세요</li><li>로봇이 비전 기능을 활용해 계단을 오릅니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td></td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결된 경우 키보드 숫자 키만 유효합니다.</em></li></ul><h3 id="wave-로봇이-부드럽게-걷도록-명령하기" tabindex="-1">Wave - 로봇이 부드럽게 걷도록 명령하기 <a class="header-anchor" href="#wave-로봇이-부드럽게-걷도록-명령하기" aria-label="Permalink to &quot;Wave - 로봇이 부드럽게 걷도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Wave&quot; 버튼</code></li><li>로봇이 Wave 보행 패턴으로 부드럽게 이동합니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td>Pitch Forward / Backward</td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결된 경우 키보드 숫자 키만 유효합니다.</em></li></ul><h3 id="sit-로봇을-앉히도록-명령하기" tabindex="-1">Sit - 로봇을 앉히도록 명령하기 <a class="header-anchor" href="#sit-로봇을-앉히도록-명령하기" aria-label="Permalink to &quot;Sit - 로봇을 앉히도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Sit&quot; 버튼</code> 또는 키보드 <code>1</code>을 누르세요</li><li>로봇이 부드럽게 앉은 자세로 전환합니다. <ul><li>📝 <em>현재 자세에 따라 전환하는 데 몇 초가 걸릴 수 있습니다.</em></li></ul></li></ul><h2 id="실제-로봇" tabindex="-1">실제 로봇 <a class="header-anchor" href="#실제-로봇" aria-label="Permalink to &quot;실제 로봇&quot;">​</a></h2><p>이 섹션에서는 <strong>실제 RBQ 로봇</strong> 작동 방법을 설명합니다.</p><p>📖 <em>상세한 작동 절차는 <a href="https://rainbowrobotics.github.io/RBQ/ko/guides/common/initial-pose.html" target="_blank" rel="noreferrer">작동 가이드</a>를 참고하세요</em></p><h3 id="_1-로봇에-연결하기" tabindex="-1">1. 로봇에 연결하기 <a class="header-anchor" href="#_1-로봇에-연결하기" aria-label="Permalink to &quot;1. 로봇에 연결하기&quot;">​</a></h3><ul><li>PC를 로봇 Wi-Fi에 연결합니다. 📝 <em>Wi-Fi SSID: <code>RBQ_xxxx</code>.</em></li></ul><h3 id="_2-gui-실행-및-로봇-제어-설정" tabindex="-1">2. GUI 실행 및 로봇 제어 설정 <a class="header-anchor" href="#_2-gui-실행-및-로봇-제어-설정" aria-label="Permalink to &quot;2. GUI 실행 및 로봇 제어 설정&quot;">​</a></h3><p><code>bin</code> 디렉토리에서 <code>GUI</code>를 실행합니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/RBQ</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/GUI</span></span></code></pre></div><ul><li><strong>Connect</strong> 버튼을 클릭합니다. <ul><li>성공하면 <code>연결 표시등</code>이 <strong>Robot Connected</strong> 텍스트와 함께 <strong>초록색</strong>으로 바뀝니다.</li></ul></li><li><strong>자동 시작</strong> 버튼을 클릭합니다. <ul><li>성공하면 <code>제어 표시등</code>이 <strong>초록색</strong>으로 변경되며, 로봇이 정상적으로 활성화되어 조작 준비가 완료된 것입니다.</li></ul></li></ul><h3 id="_3-명령은-시뮬레이션과-동일합니다" tabindex="-1">3. 명령은 시뮬레이션과 동일합니다 <a class="header-anchor" href="#_3-명령은-시뮬레이션과-동일합니다" aria-label="Permalink to &quot;3. 명령은 시뮬레이션과 동일합니다&quot;">​</a></h3><ul><li>📝 <em>실제 로봇을 조작하기 전에 먼저 시뮬레이터에서 충분히 연습해 보세요.</em></li></ul><h2 id="로봇-업데이트" tabindex="-1">로봇 업데이트 <a class="header-anchor" href="#로봇-업데이트" aria-label="Permalink to &quot;로봇 업데이트&quot;">​</a></h2><p>로봇 소프트웨어는 RBQGUI에서 갱신합니다. <code>소프트웨어 업데이트</code> 화면에서 <strong><code>UPDATE ROBOT</code></strong> 을 누르면 RBQGUI가 새 버전을 전송·설치하고 설치 로그를 보여준 뒤, 로봇 재시작 여부를 묻습니다.</p><p><strong>→ <a href="/RBQ/ko/manual/gui/robot-software-update.html">로봇 소프트웨어 업데이트</a></strong></p><p>RBQGUI 자체도 같은 화면에서 같은 방식으로 업데이트합니다.</p><p><strong>→ <a href="/RBQ/ko/manual/gui/gui-software-update.html">GUI 소프트웨어 업데이트</a></strong></p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>재시작 전에 로봇을 <strong>앉은 자세</strong>로 두고, 재시작이 끝날 때까지 움직이지 마세요. 바이너리와 스크립트 버전이 맞지 않으면 예상치 못한 동작이 생길 수 있습니다.</p></div></div><p><code>scripts/deploy.bash</code>는 로컬 개발용입니다. 방금 빌드한 바이너리를 실행한 PC의 <code>~/rbq_ws/</code>로 복사합니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/deploy.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local</span></span></code></pre></div><table tabindex="0"><thead><tr><th>인자</th><th>설명</th></tr></thead><tbody><tr><td><code>--help</code></td><td>도움말 메시지를 출력하고 종료</td></tr><tr><td><code>--local</code></td><td>동일 PC의 <code>~/rbq_ws/</code>에 배포</td></tr><tr><td><code>--pro [FILES...]</code></td><td>지정한 바이너리만 배포</td></tr></tbody></table>`,74)])])}const b=e(l,[["render",s]]);export{k as __pageData,b as default};
